    assert(a.cols == b.rows)
    result := matrix_create(a.rows, b.cols)

    for i in 0.. f32 {
    sum: f32 = 0.0
    for value in m.data {
        sum += value * value
    }
    return math.sqrt_f32(sum)
}

matrix_subtract :: proc(a: ^Matrix, b: ^Matrix) -> Matrix {
    assert(a.rows == b.rows && a.cols == b.cols)
    result := matrix_create(a.rows, a.cols)

    for i in 0..<(a.rows * a.cols) {
        result.data[i] = a.data[i] - b.data[i]
    }

    return result
}

aggregate_to_hyperedges :: proc(
    node_features: ^Matrix,
    hyperedge_indices: [][]int,
    transform: ^Matrix,
) -> Matrix {
    num_hyperedges := len(hyperedge_indices)
    hyperedge_dim := transform.rows

    hyperedge_features := matrix_create(num_hyperedges, hyperedge_dim)

    for edge_idx in 0..<num_hyperedges {
        node_indices := hyperedge_indices[edge_idx]

        for node_idx in node_indices {
            if node_idx >= 0 && node_idx < node_features.rows {
                for feat_dim in 0..<hyperedge_dim {
                    sum: f32 = 0.0
                    for node_feat_dim in 0..<node_features.cols {
                        sum += matrix_get(transform, feat_dim, node_feat_dim) * 
                               matrix_get(node_features, node_idx, node_feat_dim)
                    }
                    current := matrix_get(&hyperedge_features, edge_idx, feat_dim)
                    matrix_set(&hyperedge_features, edge_idx, feat_dim, current + sum)
                }
            }
        }

        num_nodes := f32(len(node_indices))
        if num_nodes > 0.0 {
            for feat_dim in 0..<hyperedge_dim {
                current := matrix_get(&hyperedge_features, edge_idx, feat_dim)
                matrix_set(&hyperedge_features, edge_idx, feat_dim, current / num_nodes)
            }
        }
    }

    return hyperedge_features
}

update_from_hyperedges :: proc(
    node_features: ^Matrix,
    hyperedge_features: ^Matrix,
    hyperedge_indices: [][]int,
    transform: ^Matrix,
) -> Matrix {
    updated_nodes := matrix_create(node_features.rows, node_features.cols)

    for node_idx in 0..<node_features.rows {
        for feat_dim in 0..<node_features.cols {
            matrix_set(&updated_nodes, node_idx, feat_dim, 
                      matrix_get(node_features, node_idx, feat_dim))
        }
    }

    for edge_idx in 0..<len(hyperedge_indices) {
        node_indices := hyperedge_indices[edge_idx]

        for node_idx in node_indices {
            if node_idx >= 0 && node_idx < node_features.rows {
                for node_feat_dim in 0..<node_features.cols {
                    sum: f32 = 0.0
                    for edge_feat_dim in 0..<hyperedge_features.cols {
                        sum += matrix_get(transform, node_feat_dim, edge_feat_dim) * 
                               matrix_get(hyperedge_features, edge_idx, edge_feat_dim)
                    }
                    current := matrix_get(&updated_nodes, node_idx, node_feat_dim)
                    matrix_set(&updated_nodes, node_idx, node_feat_dim, current + sum * 0.1)
                }
            }
        }
    }

    return updated_nodes
}

forward_implicit :: proc(layer: ^ImplicitHypergraphLayer) -> Matrix {
    Z := layer.node_features

    for iter in 0..<layer.max_iterations {
        H := aggregate_to_hyperedges(&Z, layer.hyperedge_indices, &layer.learnable_A)
        Z_next := update_from_hyperedges(&Z, &H, layer.hyperedge_indices, &layer.learnable_B)

        diff := matrix_subtract(&Z_next, &Z)
        norm_diff := frobenius_norm(&diff)

        if norm_diff < layer.convergence_threshold {
            return Z_next
        }

        Z = Z_next
    }

    return Z
}

initialize_implicit_hypergraph_layer :: proc(
    num_nodes: int,
    node_dim: int,
    edge_dim: int,
    hyperedges: [][]int,
    max_iters: int = 10,
    threshold: f32 = 0.001,
) -> ImplicitHypergraphLayer {
    node_features := matrix_create(num_nodes, node_dim)
    for i in 0..<(num_nodes * node_dim) {
        node_features.data[i] = f32(math.rand_f64() - 0.5) * 0.02
    }

    learnable_A := matrix_create(edge_dim, node_dim)
    for i in 0..<(edge_dim * node_dim) {
        learnable_A.data[i] = f32(math.rand_f64() - 0.5) * 0.02
    }

    learnable_B := matrix_create(node_dim, edge_dim)
    for i in 0..<(node_dim * edge_dim) {
        learnable_B.data[i] = f32(math.rand_f64() - 0.5) * 0.02
    }

    return ImplicitHypergraphLayer{
        node_features = node_features,
        hyperedge_indices = hyperedges,
        max_iterations = max_iters,
        convergence_threshold = threshold,
        learnable_A = learnable_A,
        learnable_B = learnable_B,
    }
}
