(define (normalize-multivector mv)
  (let* ([s (multivector-scalar mv)]
         [v (multivector-vector mv)]
         [bv (multivector-bivector mv)]
         [tv (multivector-trivector mv)]
         [norm-sq (+ (* s s)
                     (vector-dot v v)
                     (for/sum ([row bv])
                       (vector-dot row row))
                     (* tv tv))]
         [norm (sqrt norm-sq)])
    (if (> norm 0.0)
        (multivector (/ s norm)
                     (vector-map (lambda (x) (/ x norm)) v)
                     (vector-map (lambda (row) 
                                   (vector-map (lambda (x) (/ x norm)) row))
                                 bv)
                     (/ tv norm))
        (identity-mv 3))))
