```gleam
import gleam/list
import gleam/int
import gleam/float
import gleam/result
import src/core/clifford_kan_layer.{CliffordLayer, clifford_forward}
import src/memory/differentiable_memory.{MemoryBank, differentiable_read, differentiable_write}

pub type KANLayer {
  KANLayer(
    input_dim: Int,
    output_dim: Int,
    spline_order: Int,
    control_points: List(List(Float)),
    weights: List(List(Float)),
  )
}

pub type VSACodebook {
  VSACodebook(
    vocab_size: Int,
    hyperdim: Int,
    vectors: List(List(Int)),
  )
}

pub type TGNLayer {
  TGNLayer(
    num_nodes: Int,
    node_features: List(List(Float)),
    edge_index: List(#(Int, Int)),
    temporal_weights: List(Float),
  )
}

pub type JAIDEV32Model {
  JAIDEV32Model(
    tokenizer: Tokenizer,
    vsa_codebook: VSACodebook,
    kan_layers: List(KANLayer),
    clifford_layers: List(CliffordLayer),
    tgn_layers: List(TGNLayer),
    memory_bank: MemoryBank,
    use_memory: Bool,
  )
}

pub type Tokenizer {
  Tokenizer(
    vocab: List(String),
    vocab_size: Int,
  )
}

pub fn tokenize(tokenizer: Tokenizer, input: String) -> List(Int) {
  let chars = string_to_char_list(input)
  list.map(chars, fn(c) {
    list.index_of(tokenizer.vocab, c) |> result.unwrap(0)
  })
}

pub fn string_to_char_list(s: String) -> List(String) {
  list.range(0, string_length(s) - 1)
    |> list.map(fn(i) { string_slice(s, i, 1) })
}

pub fn string_length(s: String) -> Int {
  case s {
    "" -> 0
    _ -> 1 + string_length(string_drop_left(s, 1))
  }
}

pub fn string_slice(s: String, start: Int, length: Int) -> String {
  string_drop_left(s, start)
    |> string_take_left(length)
}

pub fn string_drop_left(s: String, n: Int) -> String {
  case n <= 0 {
    True -> s
    False -> {
      case s {
        "" -> ""
        _ -> string_drop_left(tail_string(s), n - 1)
      }
    }
  }
}

pub fn string_take_left(s: String, n: Int) -> String {
  case n <= 0 {
    True -> ""
    False -> {
      case s {
        "" -> ""
        _ -> head_string(s) <> string_take_left(tail_string(s), n - 1)
      }
    }
  }
}

pub fn head_string(s: String) -> String {
  string_slice(s, 0, 1)
}

pub fn tail_string(s: String) -> String {
  string_drop_left(s, 1)
}

pub fn vsa_encode_tokens(tokens: List(Int), codebook: VSACodebook) -> List(List(Int)) {
  list.map(tokens, fn(token_id) {
    list.at(codebook.vectors, token_id) |> result.unwrap(list.repeat(0, codebook.hyperdim))
  })
}

pub fn vsa_vectors_to_tensor(vsa_vectors: List(List(Int))) -> List(Float) {
  list.flatten(vsa_vectors)
    |> list.map(fn(x) { int.to_float(x) })
}

pub fn kan_forward_pass(layer: KANLayer, input: List(Float)) -> List(Float) {
  list.range(0, layer.output_dim - 1)
    |> list.map(fn(out_idx) {
      list.index_fold(input, 0.0, fn(acc, x, in_idx) {
        let weight = list.at(list.at(layer.weights, out_idx) |> result.unwrap([]), in_idx) |> result.unwrap(0.0)
        let spline_val = compute_spline(x, layer.spline_order, list.at(layer.control_points, out_idx) |> result.unwrap([]))
        acc +. weight *. spline_val
      })
    })
}

pub fn compute_spline(x: Float, order: Int, control_points: List(Float)) -> Float {
  case order {
    3 -> {
      let t = { x +. 1.0 } /. 2.0
      let t2 = t *. t
      let t3 = t2 *. t
      let p0 = list.at(control_points, 0) |> result.unwrap(0.0)
      let p1 = list.at(control_points, 1) |> result.unwrap(0.0)
      let p2 = list.at(control_points, 2) |> result.unwrap(0.0)
      let p3 = list.at(control_points, 3) |> result.unwrap(0.0)
      p0 *. { 1.0 -. t } *. { 1.0 -. t } *. { 1.0 -. t } +.
      3.0 *. p1 *. { 1.0 -. t } *. { 1.0 -. t } *. t +.
      3.0 *. p2 *. { 1.0 -. t } *. t2 +.
      p3 *. t3
    }
    _ -> x
  }
}

pub fn tgn_forward(layer: TGNLayer, hidden: List(Float)) -> List(Float) {
  let node_dim = list.length(hidden) / layer.num_nodes

  list.range(0, layer.num_nodes - 1)
    |> list.map(fn(node_idx) {
      let node_features = list.at(layer.node_features, node_idx) |> result.unwrap([])

      let neighbors = list.filter(layer.edge_index, fn(edge) {
        let #(from, _to) = edge
        from == node_idx
      })

      let aggregated = list.fold(neighbors, node_features, fn(acc, edge) {
        let #(_from, to) = edge
        let neighbor_features = list.at(layer.node_features, to) |> result.unwrap([])
        let temporal_weight = list.at(layer.temporal_weights, to) |> result.unwrap(1.0)
        list.zip(acc, neighbor_features)
          |> list.map(fn(pair) {
            let #(a, b) = pair
            a +. b *. temporal_weight *. 0.1
          })
      })

      aggregated
    })
    |> list.flatten
}

pub fn jaide_v32_forward(
  input: String,
  model: JAIDEV32Model,
  compute_budget: Int,
) -> List(Float) {
  let tokens = tokenize(model.tokenizer, input)
  let vsa_vectors = vsa_encode_tokens(tokens, model.vsa_codebook)
  let mut_hidden = vsa_vectors_to_tensor(vsa_vectors)

  let hidden_after_kan = list.fold(model.kan_layers, mut_hidden, fn(hidden, layer) {
    kan_forward_pass(layer, hidden)
  })

  let hidden_after_clifford = list.fold(model.clifford_layers, hidden_after_kan, fn(hidden, layer) {
    clifford_forward(hidden, layer)
  })

  let hidden_after_tgn = list.fold(model.tgn_layers, hidden_after_clifford, fn(hidden, layer) {
    tgn_forward(layer, hidden)
  })

  let final_output = case model.use_memory {
    True -> {
      let #(memory_output, _updated_memory) = differentiable_read(model.memory_bank, hidden_after_tgn)
      list.zip(hidden_after_tgn, memory_output)
        |> list.map(fn(pair) {
          let #(h, m) = pair
          h +. m *. 0.5
        })
    }
    False -> hidden_after_tgn
  }

  final_output
}

pub fn initialize_jaide_v32(
  vocab_size: Int,
  hyperdim: Int,
  hidden_dim: Int,
  num_kan_layers: Int,
  num_clifford_layers: Int,
  num_tgn_layers: Int,
  memory_slots: Int,
) -> JAIDEV32Model {
  let tokenizer = Tokenizer(
    vocab: list.range(0, vocab_size - 1) |> list.map(fn(i) { int.to_string(i) }),
    vocab_size: vocab_size,
  )

  let vsa_codebook = VSACodebook(
    vocab_size: vocab_size,
    hyperdim: hyperdim,
    vectors: list.range(0, vocab_size - 1)
      |> list.map(fn(_i) {
        list.range(0, hyperdim - 1)
          |> list.map(fn(_j) {
            case float.random() >. 0.5 {
              True -> 1
              False -> 0
            }
          })
      }),
  )

  let kan_layers = list.range(0, num_kan_layers - 1)
    |> list.map(fn(_i) {
      KANLayer(
        input_dim: hidden_dim,
        output_dim: hidden_dim,
        spline_order: 3,
        control_points: list.repeat(list.repeat(0.0, 4), hidden_dim),
        weights: list.repeat(list.repeat(0.01, hidden_dim), hidden_dim),
      )
    })

  let clifford_layers = list.range(0, num_clifford_layers - 1)
    |> list.map(fn(_i) {
      clifford_kan_layer.initialize_clifford_layer(hidden_dim, hidden_dim, 1)
    })

  let tgn_layers = list.range(0, num_tgn_layers - 1)
    |> list.map(fn(_i) {
      TGNLayer(
        num_nodes: 10,
        node_features: list.repeat(list.repeat(0.0, hidden_dim / 10), 10),
        edge_index: [(0, 1), (1, 2), (2, 3)],
        temporal_weights: list.repeat(1.0, 10),
      )
    })

  let memory_bank = differentiable_memory.initialize_memory_bank(memory_slots, hidden_dim)

  JAIDEV32Model(
    tokenizer: tokenizer,
    vsa_codebook: vsa_codebook,
    kan_layers: kan_layers,
    clifford_layers: clifford_layers,
    tgn_layers: tgn_layers,
    memory_bank: memory_bank,
    use_memory: True,
  )
}
